const input = $json.description || $json.body?.description || '';

// نظّف الضجيج
let text = input.replace(/\[cite:\s*[\d,\s]+\]/g, '')
                .split(/Need Help\?/i)[0]
                .trim();

// هل هو n8n JSON؟
try {
  const wf = JSON.parse(text);
  if (wf.nodes && wf.connections) {
    const nodes = wf.nodes
      .filter(n => !n.type.includes('stickyNote'))
      .map(n => ({
        name: n.name,
        type: n.type.split('.').pop()
      }));

    const flow = [];
    for (const [from, outs] of Object.entries(wf.connections)) {
      for (const branch of (outs.main || [])) {
        for (const c of (branch || [])) flow.push(`${from} -> ${c.node}`);
      }
    }

    return [{ json: { inputType: 'n8n-json', description: JSON.stringify({ nodes, flow }) } }];
  }
} catch (e) {}

return [{ json: { inputType: 'text', description: text.slice(0, 6000) } }];

